45	    if (AnimationController.animations.size > 0) {
46	      for (const [key, animation] of AnimationController.animations) {
47	        const now = performance.now();
48	        const deltaTime =
49	          animation.lastTime === 0 ? 0 : now - animation.lastTime;
50	
51	        const state = animation.animation({
52	          deltaTime,
53	          state: animation.state,
