1	export type AnimationCallback = (timestamp: number) => void | boolean;
2	
3	export type AnimationTarget = {
4	  callback: AnimationCallback;
5	  stopped: boolean;
6	};
7	
8	export class AnimationFrameHandler {
9	  private targets = new WeakMap<object, AnimationTarget>();
10	  private rafIds = new WeakMap<object, number>();
11	
12	  register(key: object, callback: AnimationCallback) {
13	    this.targets.set(key, { callback, stopped: true });
14	  }
15	
16	  start(key: object) {
17	    const target = this.targets.get(key);
18	
19	    if (!target) {
20	      return;
21	    }
22	
23	    if (this.rafIds.has(key)) {
24	      return;
25	    }
26	
27	    this.targets.set(key, { ...target, stopped: false });
28	    this.scheduleFrame(key);
29	  }
30	
31	  stop(key: object) {
32	    const target = this.targets.get(key);
33	    if (target && !target.stopped) {
34	      this.targets.set(key, { ...target, stopped: true });
35	    }
36	
37	    this.cancelFrame(key);
38	  }
39	
40	  private constructFrame(key: object): FrameRequestCallback {
41	    return (timestamp: number) => {
42	      const target = this.targets.get(key);
43	
44	      if (!target) {
45	        return;
46	      }
47	
48	      const shouldAbort = this.onFrame(target, timestamp);
49	
50	      if (!target.stopped && !shouldAbort) {
51	        this.scheduleFrame(key);
52	      } else {
53	        this.cancelFrame(key);
54	      }
55	    };
56	  }
57	
58	  private scheduleFrame(key: object) {
59	    const rafId = requestAnimationFrame(this.constructFrame(key));
60	
61	    this.rafIds.set(key, rafId);
62	  }
63	
64	  private cancelFrame(key: object) {
65	    if (this.rafIds.has(key)) {
66	      const rafId = this.rafIds.get(key)!;
67	
68	      cancelAnimationFrame(rafId);
69	    }
70	
71	    this.rafIds.delete(key);
72	  }
73	
74	  private onFrame(target: AnimationTarget, timestamp: number): boolean {
75	    const shouldAbort = target.callback(timestamp);
76	
77	    return shouldAbort ?? false;
78	  }
